do $$ declare def text; begin select pg_get_functiondef('finance.direct_margin_row(uuid)'::regprocedure) into def; def:=replace(def,'finance.packing_estimate(lines)', '(case when lower(coalesce(nullif(o.delivery_method,''''),o.delivery,'''')) in (''pickup'',''walkin'',''walk-in'',''counter'') then 0::numeric else finance.packing_estimate(lines) end)'); def:=replace(def,'actual:=false and receipts is not null','actual:=lower(coalesce(nullif(o.delivery_method,''''),o.delivery,'''')) in (''pickup'',''walkin'',''walk-in'',''counter'') and receipts is not null'); execute def; end $$;